ALTER POLICY commandes_files_read ON storage.objects TO authenticated USING (bucket_id = 'commandes' AND EXISTS (SELECT 1 FROM public.commandes_achat c WHERE name = ANY(c.pieces_jointes) AND public.user_in_etablissement(auth.uid(), c.etablissement_id)));
ALTER POLICY commandes_files_insert ON storage.objects TO authenticated WITH CHECK (bucket_id = 'commandes' AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.can_manage_stock(auth.uid(),e.id)));
ALTER POLICY commandes_files_delete ON storage.objects TO authenticated USING (bucket_id = 'commandes' AND owner = auth.uid() AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.can_manage_stock(auth.uid(),e.id)));
ALTER POLICY demandes_read ON storage.objects TO authenticated USING (bucket_id = 'demandes' AND EXISTS (SELECT 1 FROM public.demandes_intervention d WHERE name = ANY(d.pieces_jointes) AND public.user_in_etablissement(auth.uid(),d.etablissement_id) AND public.can_view_demande(auth.uid(),d.id)));
ALTER POLICY demandes_insert ON storage.objects TO authenticated WITH CHECK (bucket_id = 'demandes' AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.user_in_etablissement(auth.uid(),e.id)));
ALTER POLICY demandes_delete ON storage.objects TO authenticated USING (bucket_id = 'demandes' AND owner = auth.uid() AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.user_in_etablissement(auth.uid(),e.id)));
ALTER POLICY equipements_photos_select ON storage.objects TO authenticated USING (bucket_id = 'equipements' AND EXISTS (SELECT 1 FROM public.equipements e WHERE (e.photo_path = name OR e.manuel_path = name OR e.gamme_path = name) AND public.user_in_etablissement(auth.uid(),e.etablissement_id)));
ALTER POLICY equipements_photos_insert ON storage.objects TO authenticated WITH CHECK (bucket_id = 'equipements' AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.has_any_role_in(auth.uid(),e.id,ARRAY['super_admin','responsable_maintenance','responsable_etablissement','technicien']::public.app_role[])));
ALTER POLICY equipements_photos_delete ON storage.objects TO authenticated USING (bucket_id = 'equipements' AND owner = auth.uid() AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.has_any_role_in(auth.uid(),e.id,ARRAY['super_admin','responsable_maintenance','responsable_etablissement','technicien']::public.app_role[])));
ALTER POLICY equipements_photos_update ON storage.objects TO authenticated USING (false) WITH CHECK (false);
ALTER POLICY "rapports storage lecture" ON storage.objects TO authenticated USING (bucket_id = 'rapports' AND EXISTS (SELECT 1 FROM public.rapports_generes r WHERE r.fichier_path = name AND public.user_in_etablissement(auth.uid(),r.etablissement_id)));
ALTER POLICY "rapports storage ajout" ON storage.objects TO authenticated WITH CHECK (bucket_id = 'rapports' AND split_part(name,'/',2) = auth.uid()::text AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.has_any_role_in(auth.uid(),e.id,ARRAY['super_admin','responsable_maintenance','responsable_etablissement']::public.app_role[])));
CREATE POLICY rapports_owner_cleanup ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'rapports' AND owner = auth.uid() AND EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id::text = split_part(name,'/',1) AND public.user_in_etablissement(auth.uid(),e.id)));